current_to_report_overlay_hunks.after:
v_query_row_key:=p_request->>'row_key';
if p_request ? 'row_key' and (jsonb_typeof(p_request->'row_key') is distinct from 'string'
  or v_query_row_key='' or length(v_query_row_key)>512 or v_query_row_key~'[[:cntrl:]]'
  or v_tab<>'queries' or v_group_id is null or v_cycle_id is null or v_client_id is null
  or nullif(p_request->>'cursor','') is not null or v_report_scope_id is not null
  or v_publication_id is not null) then
  raise exception 'WEEKLY_SOURCE_WORKSPACE_REQUEST_INVALID' using errcode='22023';
end if;

-- Report finalise remains a separate exact invoice scope, after native
-- actor, group, cycle, client and reduced-pay-view admission.
if v_tab='finalise' and exists(select 1 from public.weekly_source_report_scopes rs
  where rs.id=v_report_scope_id and rs.self_bill_report_id is not null) then
  return private.weekly_source_self_bill_report_workspace_v1(p_request);
end if;

if v_query_row_key is not null and v_query_count<>1 then
  raise exception 'WEEKLY_SOURCE_CHECKLIST_QUERY_TARGET_STALE' using errcode='40001';
end if;

if v_query_row_key is not null then
  -- The exact scoped target comes from the unchanged native query universe
  -- before pagination. A closed or out-of-scope target never falls back to
  -- the first page; ordinary cursors and all row action proofs stay native.
  if v_publication_id is null then
    raise exception 'WEEKLY_SOURCE_CHECKLIST_QUERY_TARGET_STALE' using errcode='40001';
  end if;
  -- ALL_FILTERED authority is broader than this deliberate single-row view.
  -- Keep the row's actual explicit actions; do not advertise bulk authority.
  v_bulk_actions:='{}'::jsonb;
end if;

report_overlay_to_d10_hunks.after:
v_query_row_key text;
v_d10_target boolean:=false;
v_d10_groups jsonb;
v_d10_rows jsonb;
v_d10_count integer;
